    PerformanceMeasurement.add_member(:percent_of_total_traffic_impacted, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'PercentOfTotalTrafficImpacted', traits: {"smithy.api#documentation" => "<p>The impact on total traffic that a health event has, in increased latency or reduced availability. This is the \n\t\t\tpercentage of how much latency has increased or availability has decreased during the event, compared to what is typical for traffic from this \n\t\t\tclient location to the Amazon Web Services location using this client network.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/CloudWatch-IM-inside-internet-monitor.html#IMHealthEventStartStop\">When Amazon Web Services creates and resolves health\n\t\t\tevents</a> in the Amazon CloudWatch Internet Monitor section of the <i>CloudWatch User Guide</i>.</p>"}))
    PerformanceMeasurement.add_member(:percent_of_client_location_impacted, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'PercentOfClientLocationImpacted', traits: {"smithy.api#documentation" => "<p>How much performance impact was caused by a health event at a client location. For performance, this is the percentage of how much latency increased\n\t\t\tduring the event compared to typical performance for traffic, from this client location to an Amazon Web Services location, using a specific client network. </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/CloudWatch-IM-inside-internet-monitor.html#IMHealthEventStartStop\">When Amazon Web Services creates and resolves health\n\t\t\tevents</a> in the Amazon CloudWatch Internet Monitor section of the <i>CloudWatch User Guide</i>.</p>"}))
    PerformanceMeasurement.add_member(:round_trip_time, Smithy::Schema::Shapes::ShapeRef.new(shape: RoundTripTime, location_name: 'RoundTripTime', traits: {"smithy.api#documentation" => "<p>This is the percentage of how much round-trip time increased during the event compared to typical round-trip time for your application for traffic. </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/CloudWatch-IM-inside-internet-monitor.html#IMHealthEventStartStop\">When Amazon Web Services creates and resolves health\n\t\t\tevents</a> in the Amazon CloudWatch Internet Monitor section of the <i>CloudWatch User Guide</i>.</p>"}))
