    UpdateMonitorInput.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'ClientToken', traits: {"smithy.api#documentation" => "<p>A unique, case-sensitive string of up to 64 ASCII characters that you specify to make an idempotent API request. You should not reuse the same client\n\t\t\ttoken for other API requests.</p>", "smithy.api#idempotencyToken" => {}}))
