    UpdateMonitorInput.add_member(:internet_measurements_log_delivery, Smithy::Schema::Shapes::ShapeRef.new(shape: InternetMeasurementsLogDelivery, location_name: 'InternetMeasurementsLogDelivery', traits: {"smithy.api#documentation" => "<p>Publish internet measurements for Internet Monitor to another location, such as an Amazon S3 bucket. The measurements are also published to Amazon CloudWatch Logs.</p>"}))
    UpdateMonitorInput.add_member(:traffic_percentage_to_monitor, Smithy::Schema::Shapes::ShapeRef.new(shape: TrafficPercentageToMonitor, location_name: 'TrafficPercentageToMonitor', traits: {"smithy.api#documentation" => "<p>The percentage of the internet-facing traffic for your application that you want to monitor with this monitor. If you set a city-networks\n\t\t\tmaximum, that limit overrides the traffic percentage that you set.</p>\n         <p>To learn more, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/IMTrafficPercentage.html\">Choosing an application traffic percentage to monitor\n\t\t</a> in the Amazon CloudWatch Internet Monitor section of the <i>CloudWatch User Guide</i>.</p>"}))
